export function initProjectUpdates(){
 const $=selector=>document.querySelector(selector),root=$('#acoes-projetos'),dialog=$('#update-dialog'),form=$('#update-form'),filters=$('#updates-filters'),feedback=$('#update-feedback');
 let catalog=[],items=[],page=1,total=0,editing=null,photos=[],step=0,dirty=false,busy=false,loaded=false,requestVersion=0,lastFocus;
 const today=()=>new Date(Date.now()-10800000).toISOString().slice(0,10);
 const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 const field=name=>form.elements.namedItem(name);
 async function api(path,options={}){const response=await fetch(path,{cache:'no-store',...options});let data;try{data=await response.json();}catch{throw Error('Não foi possível confirmar a resposta. Reabra a ação antes de repetir o envio.');}if(!response.ok)throw Error(data.error||'Não foi possível concluir a operação.');return data;}
 async function projects(){const data=await api('/api/admin/projetos-site');catalog=data.items;for(const [select,label]of [[$('#updates-project-filter'),'Todos os projetos'],[field('projeto_publico_id'),'Escolha o projeto']]){const previous=select.value;select.replaceChildren(new Option(label,''));if(select===field('projeto_publico_id')){select.options[0].disabled=true;select.add(new Option('Ação geral do Instituto (sem projeto)','__geral'));}for(const p of catalog)select.add(new Option(p.titulo+(p.publicada?'':' · rascunho'),p.id));if([...select.options].some(o=>o.value===previous))select.value=previous;}}
 function isBusy(value){busy=value;for(const control of form.querySelectorAll('button,input,textarea,select'))control.disabled=value;$('#update-close').disabled=value;}
 function setStep(value){step=Math.max(0,Math.min(2,value));for(const section of form.querySelectorAll('[data-update-step]'))section.hidden=Number(section.dataset.updateStep)!==step;for(const [i,item]of [...form.querySelectorAll('.update-steps li')].entries()){if(i===step)item.setAttribute('aria-current','step');else item.removeAttribute('aria-current');}$('#update-back').hidden=step===0;$('#update-continue').hidden=step===2;$('#update-publish').hidden=step!==2;renderPreview();dialog.querySelector('.dialog-body').scrollTop=0;if(dialog.open){const heading=form.querySelector('[data-update-step="'+step+'"] legend');heading.tabIndex=-1;heading.focus();}}
 function validBasics(){for(const name of ['projeto_publico_id','titulo','data_realizacao'])if(!field(name).checkValidity()){setStep(0);field(name).reportValidity();return false;}return true;}
 function renderPreview(){const target=$('#update-preview');target.replaceChildren(el('h3',field('titulo').value||'Título da ação'),el('p',field('data_realizacao').value||''));for(const name of ['resumo','conteudo'])if(field(name).value)target.append(el('p',field(name).value,'update-preview-text'));const gallery=el('div',undefined,'update-preview-photos');for(const p of photos){const figure=el('figure'),image=el('img');image.src=p.caminho;image.alt=p.descricao||'Foto em revisão';figure.append(image);if(p.legenda)figure.append(el('figcaption',p.legenda));gallery.append(figure);}target.append(gallery);}
 function renderPhotos(){const target=$('#update-photos');target.replaceChildren();photos.forEach((photo,index)=>{const card=el('article',undefined,'update-photo'),image=el('img');image.src=photo.caminho;image.alt=photo.descricao||'Foto '+(index+1)+' em revisão';image.width=500;image.height=375;card.append(image);for(const [name,label,max]of [['descricao','Descrição da imagem *',200],['legenda','Legenda (opcional)',300]]){const wrapper=el('label',label),input=el('input');input.type='text';input.value=photo[name]||'';input.maxLength=max;input.placeholder=name==='descricao'?'Ex.: Equipe preparando as cestas para entrega':'Uma frase para acompanhar a foto';input.addEventListener('input',()=>{photo[name]=input.value;dirty=true;if(name==='descricao')image.alt=input.value||'Foto em revisão';renderPreview();});wrapper.append(input);card.append(wrapper);}const actions=el('div',undefined,'actions');for(const [label,delta]of [['Subir',-1],['Descer',1]]){const button=el('button',label,'button secondary');button.type='button';button.disabled=index+delta<0||index+delta>=photos.length;button.onclick=()=>{[photos[index],photos[index+delta]]=[photos[index+delta],photos[index]];dirty=true;renderPhotos();renderPreview();};actions.append(button);}const remove=el('button','Remover foto','text-button');remove.type='button';remove.onclick=()=>{photos.splice(index,1);dirty=true;field('fotos_autorizadas').checked=false;renderPhotos();renderPreview();};actions.append(remove);card.append(actions);target.append(card);});if(!photos.length)target.append(el('p','Você pode publicar só o texto ou adicionar fotos da atividade.','update-hint'));$('.update-consent').hidden=!photos.length;}
 function renderList(){const target=$('#updates-list');target.replaceChildren();for(const item of items){const card=el('article',undefined,'panel update-card'),body=el('div');body.append(el('span',item.publicada?(item.projeto_publico_id&&!item.projeto_publicado?'Projeto em rascunho · ação fora do site':'Publicada no site'):'Rascunho','badge '+(item.publicada?'published':'draft')),el('h3',item.titulo),el('p',(item.projeto_titulo||'Ação geral do Instituto')+' · '+item.data_realizacao.split('-').reverse().join('/')),el('p',item.resumo||'Resumo ainda não preenchido.'),el('small',item.fotos.length+' foto(s) · Atualizada em '+new Date(item.atualizado_em).toLocaleString('pt-BR')));const actions=el('div',undefined,'actions'),edit=el('button','Editar relato','button secondary');edit.type='button';edit.onclick=()=>open({id:item.id});actions.append(edit);const remove=el('button','Excluir relato','button update-delete-control');remove.type='button';remove.setAttribute('aria-label','Excluir relato '+item.titulo);remove.onclick=()=>removeUpdate(item);actions.append(remove);if(item.projeto_publico_id){const link=el('a',item.publicada&&item.projeto_publicado?'Ver no site':'Ver prévia','text-button');link.href='/projeto-'+item.projeto_publico_id+'.html?acao='+item.id+(item.publicada&&item.projeto_publicado?'':'&preview=1')+'#acao-'+item.id;link.target='_blank';link.rel='noopener';actions.append(link);}body.append(actions);card.append(body);if(item.fotos[0]){const img=el('img');img.src=item.fotos[0].caminho;img.alt=item.fotos[0].descricao||'Foto em revisão';img.loading='lazy';card.append(img);}target.append(card);}if(!items.length)target.append(el('div','Nenhuma ação nesta seleção. Use Registrar uma ação para contar o que aconteceu.','panel empty-state'));$('#updates-status').textContent=total+' ação(ões) nesta seleção';$('#updates-page').textContent='Página '+page+' de '+Math.max(1,Math.ceil(total/20));$('#updates-prev').disabled=page<=1;$('#updates-next').disabled=page*20>=total;}
 async function load(){const ownVersion=++requestVersion;$('#updates-status').textContent='Carregando ações…';try{const params=new URLSearchParams(new FormData(filters));params.set('pagina',page);const data=await api('/api/admin/atualizacoes?'+params);if(ownVersion!==requestVersion)return false;items=data.items;total=data.total;renderList();loaded=true;return true;}catch(error){if(ownVersion===requestVersion)$('#updates-status').textContent=error.message;return false;}}
 async function ensureLoaded(){if(loaded)return;try{await projects();await load();}catch(error){$('#updates-status').textContent=error.message;}}
 async function open({id,projectId}={}){if(busy)return;if(dialog.open&&dirty&&!confirm('Há alterações não salvas. Deseja descartá-las?'))return;lastFocus=document.activeElement;feedback.textContent='';try{await projects();const item=id?(await api('/api/admin/atualizacoes?id='+encodeURIComponent(id))).item:null;form.reset();editing=item;photos=(item?.fotos||[]).map(p=>({...p}));for(const name of ['titulo','resumo','conteudo'])field(name).value=item?.[name]||'';field('data_realizacao').max=today();field('data_realizacao').value=item?.data_realizacao||today();field('projeto_publico_id').value=item?(item.projeto_publico_id||'__geral'):(projectId||filters.elements.projeto.value||'');field('fotos_autorizadas').checked=!!item?.fotos_autorizadas;$('#update-title').textContent=item?'Editar ação':'Registrar uma ação';$('#update-delete').hidden=!item;$('#update-upload-status').textContent='';$('#update-files').value='';dirty=false;renderPhotos();setStep(0);if(!dialog.open)dialog.showModal();field('projeto_publico_id').focus();}catch(error){$('#updates-status').textContent=error.message;}}
 async function removeUpdate(item){
  if(!item||busy)return;
  const fromEditor=dialog.open&&editing?.id===item.id;
  const question=(fromEditor&&dirty?'Há alterações não salvas nesta edição. ':'')+'Excluir definitivamente o relato “'+item.titulo+'” e sua galeria de fotos? Esta ação não pode ser desfeita.';
  if(!window.confirm(question))return;
  isBusy(true);root.setAttribute('aria-busy','true');
  const target=fromEditor?feedback:$('#updates-status');target.textContent='Excluindo relato…';
  try{
   const result=await api('/api/admin/atualizacoes/excluir',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:item.id,versao:item.versao,confirmacao:item.id})});
   if(editing?.id===item.id){dirty=false;editing=null;photos=[];dialog.close();$('#update-delete').hidden=true;}
   if(items.some(row=>row.id===item.id))page=Math.min(page,Math.max(1,Math.ceil(Math.max(0,total-1)/20)));
   const refreshed=await load();
   window.dispatchEvent(new CustomEvent('admin-data-updated',{detail:{origin:'project-updates',periodo:result.periodo}}));
   $('#updates-status').textContent=refreshed?'Relato excluído. A publicação e sua galeria foram removidas do projeto.':'Relato excluído. Faça uma nova busca para atualizar a lista.';
   $('#update-new').focus();
  }catch(error){target.textContent=error.message;if(fromEditor)feedback.focus();}
  finally{isBusy(false);root.removeAttribute('aria-busy');}
 }
 function close(){if(busy)return;if(dirty&&!confirm('Há alterações não salvas. Deseja fechar a edição e descartá-las?'))return;dialog.close();dirty=false;editing=null;lastFocus?.focus();}
 $('#update-delete').onclick=()=>removeUpdate(editing);$('#update-close').onclick=close;dialog.addEventListener('cancel',event=>{event.preventDefault();close();});$('#update-new').onclick=()=>open();$('#update-back').onclick=()=>setStep(step-1);$('#update-continue').onclick=()=>{if(step===0&&!validBasics())return;setStep(step+1);};form.addEventListener('input',()=>{dirty=true;renderPreview();});
 $('#update-files').addEventListener('change',async event=>{const files=[...event.target.files],status=$('#update-upload-status');if(!files.length)return;if(files.length+photos.length>8){status.textContent='Adicione até 8 fotos por ação.';event.target.value='';return;}if(files.some(file=>!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)){status.textContent='Escolha fotos JPG, PNG ou WebP de até 5 MB cada.';event.target.value='';return;}isBusy(true);try{for(const [index,file]of files.entries()){status.textContent='Enviando foto '+(index+1)+' de '+files.length+'…';const result=await api('/api/admin/atualizacoes/foto',{method:'POST',headers:{'Content-Type':file.type},body:file});photos.push({caminho:result.capa,descricao:'',legenda:''});dirty=true;field('fotos_autorizadas').checked=false;}status.textContent='Fotos enviadas. Descreva as imagens e salve o relato para guardar a galeria.';}catch(error){status.textContent=error.message;}finally{isBusy(false);event.target.value='';renderPhotos();renderPreview();}});
 form.addEventListener('submit',async event=>{event.preventDefault();if(busy||!validBasics())return;const publish=event.submitter?.value==='publicar',project=field('projeto_publico_id').value,body={titulo:field('titulo').value,resumo:field('resumo').value,conteudo:field('conteudo').value,data_realizacao:field('data_realizacao').value,projeto_publico_id:project==='__geral'?null:project,publicada:publish,fotos_autorizadas:field('fotos_autorizadas').checked,fotos:photos.map(({caminho,descricao,legenda})=>({caminho,descricao,legenda}))};if(editing){body.id=editing.id;body.versao=editing.versao;}if(publish&&body.resumo.trim().length<10){setStep(1);feedback.textContent='Escreva um resumo com pelo menos 10 caracteres para publicar.';field('resumo').focus();return;}if(publish&&photos.length&&project==='__geral'){setStep(0);feedback.textContent='Escolha um projeto para publicar a galeria de fotos.';field('projeto_publico_id').focus();return;}if(publish&&photos.some(photo=>photo.descricao.trim().length<3)){setStep(2);feedback.textContent='Descreva cada foto antes de publicar.';feedback.focus();return;}if(publish&&photos.length&&!body.fotos_autorizadas){setStep(2);feedback.textContent='Confirme a autorização de publicação das imagens.';field('fotos_autorizadas').focus();return;}if(!publish&&editing?.publicada&&!confirm('Salvar como rascunho retira este relato e suas fotos do site. Continuar?'))return;isBusy(true);feedback.textContent='Salvando ação…';try{await api('/api/admin/atualizacoes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});dirty=false;dialog.close();editing=null;await load();window.dispatchEvent(new CustomEvent('admin-data-updated',{detail:{origin:'project-updates',periodo:body.data_realizacao.slice(0,7)}}));$('#updates-status').textContent=publish?'Ação publicada. O relato já aparece na página do projeto.':'Rascunho salvo. Você pode continuar a edição quando quiser.';lastFocus?.focus();}catch(error){feedback.textContent=error.message;feedback.focus();}finally{isBusy(false);renderPhotos();}});
 filters.onsubmit=event=>{event.preventDefault();page=1;load();};$('#updates-project-filter').onchange=()=>{page=1;load();};$('#updates-prev').onclick=()=>{page--;load();};$('#updates-next').onclick=()=>{page++;load();};
 window.addEventListener('beforeunload',event=>{if(dirty||busy){event.preventDefault();event.returnValue='';}});
 window.addEventListener('public-projects-updated',()=>{loaded=false;if(!root.hidden)ensureLoaded();});
 window.addEventListener('admin-data-updated',event=>{if(event.detail?.origin==='project-updates')return;loaded=false;if(!root.hidden)ensureLoaded();});
 window.addEventListener('project-updates-open',async event=>{location.hash='acoes-projetos';try{await projects();filters.elements.projeto.value=event.detail?.projectId||'';page=1;await load();}catch(error){$('#updates-status').textContent=error.message;}});
 return {ensureLoaded,open};
}
